<?php
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
add_action('admin_menu',function(){add_management_page('Site Migrations','Site Migrations','manage_options','eyedonation-migrations',__NAMESPACE__.'\\admin_screen');});
add_action('wp_ajax_edm_batch',function(){if(!current_user_can('manage_options'))wp_send_json_error(['message'=>'Unauthorized'],403);check_ajax_referer('edm_run');if(empty($_POST['backup']))wp_send_json_error(['message'=>'Administrator backup acknowledgment required.'],400);try{wp_send_json_success(batch(sanitize_key(wp_unslash($_POST['migration']??''))));}catch(\Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],409);}});
add_action('admin_post_edm_report',function(){if(!current_user_can('manage_options'))wp_die('Unauthorized',403);check_admin_referer('edm_report');header('Content-Type: application/json');header('Content-Disposition: attachment; filename="eyedonation-migration-report.json"');echo wp_json_encode(['site'=>home_url(),'environment'=>wp_get_environment_type(),'release'=>VERSION,'history'=>history(),'preview'=>get_option('edm_preview')],JSON_PRETTY_PRINT);exit;});
function admin_screen(){if(!current_user_can('manage_options'))return;$message='';if($_SERVER['REQUEST_METHOD']==='POST'){check_admin_referer('edm_preview');try{preview();$message='Preview saved. No target records changed.';}catch(\Throwable $e){$message=$e->getMessage();}}
 $preview=get_option('edm_preview',[]);$history=history();echo '<div class="wrap"><h1>Site Migrations</h1><p>Project EyeDonation · '.esc_html(home_url()).' · '.esc_html(wp_get_environment_type()).' · active theme '.esc_html(get_stylesheet().' '.wp_get_theme()->get('Version')).' · migration release '.esc_html(VERSION).'</p><p role="status" id="edm-status">'.esc_html($message).'</p><form method="post">';wp_nonce_field('edm_preview');submit_button('Preview Changes');echo '</form><p><label><input id="edm-backup" type="checkbox"> I acknowledge that I have taken a recoverable backup. This acknowledgment does not verify a backup exists.</label></p><table class="widefat"><thead><tr><th>Migration</th><th>Purpose and prerequisites</th><th>Status / preview</th><th>Actions</th></tr></thead><tbody>';
 foreach(registry() as $id=>$m){$row=$preview['rows'][$id]??[];$saved=$history[$id]??[];$status=$saved['status']??$row['status']??'pending';if($status==='running'&&($saved['heartbeat']??0)<time()-90)$status='interrupted';echo '<tr><td>'.esc_html($id).'</td><td>'.esc_html($m['description']).'<br>Dependencies: '.esc_html(implode(', ',$m['dependencies'])?:'none').'</td><td>'.esc_html($status).' '.esc_html(isset($saved['completed'])?gmdate('c',$saved['completed']):'').'<br>'.esc_html($row['reason']??$saved['error']??'');foreach($row['operations']??[] as $op)echo '<details><summary>'.esc_html($op['key'].' — '.$op['action']).'</summary><pre>'.esc_html(wp_json_encode(['fields'=>$op['kind']==='post'||$op['kind']==='page'?['post_content']:[$op['key']],'before'=>$op['before'],'after'=>$op['after']],JSON_PRETTY_PRINT)).'</pre></details>';echo '</td><td><button type="button" class="button edm-process" data-migration="'.esc_attr($id).'" '.(($row['status']??'')!=='ready'?'disabled':'').'>'.esc_html(in_array($status,['failed','running','interrupted'],true)?'Resume / Retry':'Process Migrations').'</button></td></tr>';}
 echo '</tbody></table><h2>Media preflight</h2><table class="widefat"><tr><th>Asset</th><th>Expected path</th><th>Destination</th><th>Status</th></tr>';foreach($preview['assets']??[] as $key=>$a)echo '<tr><td>'.esc_html($key).'</td><td>'.esc_html($a['path']).'</td><td>'.esc_html(($a['id']??'').' '.($a['url']??'')).'</td><td>'.esc_html($a['status']).'</td></tr>';echo '</table><p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=edm_report'),'edm_report')).'">Download Report</a></p></div>';
 wp_enqueue_script('edm-admin',plugins_url('../assets/admin.js',__FILE__),[],VERSION,true);wp_add_inline_script('edm-admin','window.edmNonce='.wp_json_encode(wp_create_nonce('edm_run')).';','before');
}
